import React, { useState, useEffect, useCallback } from 'react';
import axios from 'axios';

// ✅ Correct base URL (no extra /api/medicines)
const API_BASE_URL = 'http://localhost:9091';

function UserShop({ token, setMessage }) {
  const [medicines, setMedicines] = useState([]);
  const [search, setSearch] = useState('');

  // ✅ Fetch data from correct endpoint
  const fetchMedicines = useCallback(async () => {
    try {
      const response = await axios.get(`${API_BASE_URL}/api/user/medicines`, {
        headers: { Authorization: `Bearer ${token}` }
      });
      setMedicines(response.data);
    } catch (error) {
      console.error('Error fetching user shop data:', error);
      setMessage({
        type: 'error',
        text: 'Failed to load medicines. Please check your backend connection or token.',
      });
    }
  }, [token, setMessage]);

  useEffect(() => {
    fetchMedicines();
  }, [fetchMedicines]);

  const filteredMedicines = medicines.filter((med) =>
    med.name.toLowerCase().includes(search.toLowerCase()) ||
    med.description.toLowerCase().includes(search.toLowerCase())
  );

  return (
    <div className="p-4 max-w-7xl mx-auto">
      <h2 className="text-3xl font-bold text-indigo-700 mb-6">
        Welcome to the Pharmacy Shop!
      </h2>

      <div className="bg-blue-100 p-4 rounded-lg shadow-md mb-6">
        <p className="text-blue-800 font-medium">
          <span className="font-extrabold mr-2">Note for Demo:</span> This is
          the USER view. It only shows the available items. In a full app, "Add
          to Cart" and "Checkout" features would be here.
        </p>
      </div>

      <input
        type="text"
        placeholder="Search for medicine..."
        value={search}
        onChange={(e) => setSearch(e.target.value)}
        className="w-full px-4 py-2 border border-gray-300 rounded-lg focus:ring-indigo-500 focus:border-indigo-500 shadow-sm mb-6"
      />

      <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-6">
        {filteredMedicines.map((med) => (
          <div
            key={med.id}
            className="bg-white p-6 rounded-xl shadow-lg border border-gray-200"
          >
            <h3 className="text-xl font-bold text-gray-900 mb-2">{med.name}</h3>
            <p className="text-gray-600 text-sm mb-4 line-clamp-2">
              {med.description}
            </p>
            <div className="flex justify-between items-center">
              <span className="text-2xl font-extrabold text-green-600">
                ₹{med.price.toFixed(2)}
              </span>
              <span
                className={`text-sm font-semibold p-1 rounded-full ${
                  med.stockQuantity > 0
                    ? 'bg-green-100 text-green-700'
                    : 'bg-red-100 text-red-700'
                }`}
              >
                Stock: {med.stockQuantity > 0 ? med.stockQuantity : 'Out'}
              </span>
            </div>
            <button
              disabled={med.stockQuantity === 0}
              className="w-full mt-4 px-4 py-2 bg-indigo-500 text-white font-semibold rounded-lg disabled:bg-gray-400 cursor-not-allowed"
            >
              Add to Cart (Disabled for Demo)
            </button>
          </div>
        ))}
      </div>

      {filteredMedicines.length === 0 && (
        <p className="text-center py-8 text-gray-500 text-lg">
          No medicines found.
        </p>
      )}
    </div>
  );
}

export default UserShop;


